/** Validate packs already generated by the real capture command. */
import fs from 'node:fs';import assert from 'node:assert/strict';import crypto from 'node:crypto';
import {defectReport} from '../web/product/defect-report.js';
const root='review/defects';
for(const id of ['case-001','case-003','case-004-private']){
 const dir=root+'/'+id,meta=JSON.parse(fs.readFileSync(dir+'/metadata.json','utf8'));
 for(const key of ['sceneId','imageSize','viewportSize','productId','pattern','boardWidthMeters','boardLengthMeters','floorAngle','geometryStatus','horizon','vanishingPoints','cameraHeight','scaleNear','scaleMid','scaleFar','maskCoverage','ViewTransform'])assert.ok(Object.hasOwn(meta,key),'Missing '+key);
 for(const name of ['01-original','02-render','03-debug-grid','04-debug-masks','05-debug-camera','06-debug-scale']){
  const data=fs.readFileSync(dir+'/'+name+'.png');assert.equal(data.toString('ascii',1,4),'PNG');
  assert.equal(data.readUInt32BE(16),meta.imageSize.width);assert.equal(data.readUInt32BE(20),meta.imageSize.height);
 }
 const report=defectReport(JSON.parse(fs.readFileSync(dir+'/defect-report.json','utf8')));assert.equal(report.sceneId,meta.sceneId);
 assert.match(fs.readFileSync(dir+'/defect-report.txt','utf8'),/CONFIRMED CORRECT/);
 assert.doesNotMatch(JSON.stringify(meta),/https?:\/\/|blob:|[A-Za-z]:\\|C:\//i,'Unnecessary private path/URL in metadata');
}
const blocked=JSON.parse(fs.readFileSync(root+'/case-005-blocked/metadata.json','utf8'));assert.equal(blocked.renderBlocked,true);assert.equal(blocked.renderAvailable,false);
const dir=root+'/case-004-private',meta=JSON.parse(fs.readFileSync(dir+'/metadata.json','utf8'));
assert.ok(meta.originalNativeSize.width>=meta.imageSize.width);
const hash=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
if(process.env.PPAI_PRIVATE_ORIGINAL)assert.equal(hash(dir+'/00-original-native.png'),hash(process.env.PPAI_PRIVATE_ORIGINAL));else console.log('Original byte-identity check requires PPAI_PRIVATE_ORIGINAL');
assert.ok(fs.existsSync(root+'/index.html'));
console.log('PASS three real packs: required metadata, source-sized PNGs, report schema, privacy checks and original-native byte preservation');
